    "niveau": 2,
    "type": "liste",
    "recto": "Quels archétypes Strauss et Howe associent-ils aux générations ?",
    "verso": "Héros, Artiste, Prophète, Nomade.",
    "ancre": "s-2-le-consommateur-contemporain",
