    "verso": "Le 6e M est Mesures : la façon même d'observer et de chiffrer peut créer l'écart constaté.\nLes 6M : Machines (Moyens), Méthodes, Matériaux (Matières), Mère Nature (Milieu), Main-d'œuvre, Mesures.",
